const o = phi.observe({ maxElements: 30 });
const btns = o.nodes.map(n => `${n.ref}. ${n.role} "${(n.name||n.text||'').slice(0,60)}"`);
const frames = phi.js(() => {
  const list = [];
  const walk = (doc, path) => {
    const els = doc.querySelectorAll('button, [role=button], div[class*=hold], div[id*=hold], iframe');
    els.forEach(e => {
      const r = e.getBoundingClientRect();
      list.push({ tag: e.tagName, id: e.id, cls: (e.className||'').toString().slice(0,60), txt: (e.textContent||'').trim().slice(0,40), rect: [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)] });
    });
  };
  walk(document, 'top');
  return list.slice(0, 40);
});
return { btns, frames };

const dims = phi.js(() => ({ w: innerWidth, h: innerHeight, dpr: devicePixelRatio, sw: scrollX, sy: scrollY }));
const sx = dims.w / 1600;
const x = Math.round(836 * sx), y = Math.round(688 * sx);
phi.narrate("pressing and holding the human check, then waiting it out");
phi.cdp("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
phi.cdp("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", clickCount: 1, buttons: 1 });
phi.sleep(9000);
phi.cdp("Input.dispatchMouseEvent", { type: "mouseReleased", x, y, button: "left", clickCount: 1, buttons: 0 });
phi.sleep(2500);
return { dims, x, y, frames: phi.query("iframe").total, text: phi.text().slice(0, 600) };

const obs = phi.observe({ viewportOnly: true, maxElements: 12 });
