const obs = phi.observe({ maxElements: 300 });
const interesting = obs.nodes.filter(n => /Diet|Veget|Price|Filter|Sort|\$/.test((n.name||"") + " " + (n.text||"")));
return { total: obs.total, interesting: interesting.map(n => `${n.ref}. ${n.role} name=${n.name||""} text=${n.text||""}`) };

const obs = phi.observe({ viewportOnly: true, maxElements: 30 });
const f = obs.nodes.find(n => /Filters Menu/.test(n.name || ""));
let res = null;
if (f) res = phi.click(f.ref);
phi.sleep(1500);
const obs2 = phi.observe({ maxElements: 120 });
const items = obs2.nodes.map(n => `${n.ref}. ${n.role} name=${n.name||""} text=${n.text||""}`);
return { clicked: f ? f.ref : null, res, url: obs2.url, total: obs2.total, nodes: items.filter(s => /Veget|Diet|Price|\$|Filter|Crust|brand|Brand/i.test(s)).slice(0, 60) };

const obs = phi.observe({ maxElements: 350 });
