return { clicked: price && price.ref, res, url: obs2.url, total: obs2.total, nodes: now.map(n => `${n.ref}. ${n.role} name=${(n.name||"").slice(0,120)}`).slice(0,80) };

const obs = phi.observe({ maxElements: 400 });
const cb = obs.nodes.find(n => n.role === "checkbox" && /\$5\s*–\s*\$9\.99/.test(n.name || ""));
