  filt: obs3.nodes.filter(n => /Dietary|Veget|Price|See results|checkbox|caption|Filter/i.test((n.role||"")+" "+(n.name||""))).map(n => `${n.ref}. ${n.role} ${(n.name||"").slice(0,80)}`).slice(0,40) };

